-- Preserve the host-selected duration when start/replay replaces the room state.
CREATE OR REPLACE FUNCTION public.igr_v35_apply_room_duration()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_mode text; v_kind text; v_seconds integer; begin if tg_op='INSERT' then if coalesce(new.state->>'duration_mode','') not in ('short','long') then new.state:=jsonb_set(coalesce(new.state,'{}'::jsonb),'{duration_mode}',to_jsonb('long'::text),true); end if; return new; end if; if coalesce(new.state->>'duration_mode','') not in ('short','long') and coalesce(old.state->>'duration_mode','') in ('short','long') then new.state:=jsonb_set(coalesce(new.state,'{}'::jsonb),'{duration_mode}',old.state->'duration_mode',true);end if; v_mode:=new.state->>'duration_mode'; if coalesce(v_mode,'') not in ('short','long') then return new; end if; if not (new.phase is distinct from old.phase or new.phase_started_at is distinct from old.phase_started_at) or new.phase_started_at is null then return new; end if; if new.phase='final_debrief' and public.igr_v44_judge_present(new.code) then v_seconds:=case when v_mode='short' then 180 else 240 end; else v_kind:=case new.phase when 'initial_debrief' then 'pre_investigation' when 'interrogation' then 'interrogation' when 'cycle_debrief' then 'cycle_debrief' when 'event_confrontation' then 'confrontation' when 'event_assembly' then 'assembly' when 'event_requete' then 'judicial_short' when 'event_saisine' then 'judicial_short' when 'annex_juge' then 'judicial_long' when 'annex_temoin' then 'witness' when 'final_debrief' then 'final_debrief' else null end; if v_kind is not null then v_seconds:=public.igr_v35_duration_seconds(v_mode,v_kind); end if; end if; if v_seconds is not null then new.phase_ends_at:=new.phase_started_at+make_interval(secs=>v_seconds); end if; return new; end $function$
;
